import bisect

def solve(n, x, stations):
    left, right = 1, min(stations) * 2

    def dp(mid, gas):
        cur_gas, pos = gas, 0
        for station in stations:
            if station - pos >= mid:
                cur_gas += mid
                pos = station + mid
            else:
                cur_gas -= (station - pos)
                pos = station
        return cur_gas >= 0 and (pos + mid <= x)

    while left < right:
        mid = (left + right) // 2
        if dp(mid, x):
            right = mid
        else:
            left = mid + 1

    return left

