import math
from functools import lru_cache

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

@lru_cache(512)
def factorize(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            power = 0
            while n % i == 0:
                n //= i
                power += 1
            factors.append((i, power))
            i = max(i, i + 1)
    if n != 1:
        factors.append((n, 1))
    return tuple(sorted(factors))

def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))
        total_power = 0
        pows = {}
        for i, v in enumerate(a):
            factors = factorize(v)
            g = 1
            for prime, power in factors:
                g -= (g // (prime ** power)) * ((prime ** (power + 1)) - 1)
            total_power += g
            for p in range(2, len(factors) if factors else gcd(total_power, v)):
                if p not in pows:
                    pows[p] = 0
                pows[p] += (g // (p ** (len(factors) if factors else total_power <= v else gcd(total_power, v))) + 1)
        pows_list = list(pows.values())
        min_diff = math.inf
        for i in range(1, len(pows_list) - k + 1):
            diff = sum(pows_list[i:i+k]) - sum(pows_list[:i])
            min_diff = min(min_diff, diff)
        print(min_diff)

