import re

@lru_cache(maxsize=None)
def get_next_numbers(n, s):
    patterns = [
        f"({s}[0-9]+){[0-9]}{s}$",
        f"^({s}[0-9]+)([0-9]).+$",
        f"^({s}[0-9]*)$"
    ]
