class FenwickTree:
    def __init__(self, n):
        self.bit = [0] * (n + 1)
        self.n = n

    def update(self, k, delta):
        for i in range(k, self.n + 1):
            self.bit[i] += delta
            self.bit[i + ((i & -i) - 1)] += delta

    def sum(self, k):
        total = 0
        for i in range(k + 1, 0, -(k & -k)):
            total += self.bit[i]
        return total

def build(A, n):
