def solve():
    n = int(input())
    for _ in range(n):
        string_length = int(input())
        edges = {}
        reverse_edges = {}
        for _ in range(2 * string_length - 2):
            substring = input().strip()
            start = ord(substring[0])
            end = ord(substring[-1]) + 1
            if start not in edges:
                edges[start] = []
            heapq.heappush(edges[start], -end)
            reverse_edges[end] = [*-1 * i for i in edges[start]]
        parent = [-1] * (26 + 10 ** 5)
        rank = [0] * (26 + 10 ** 5)
        for length in range(2, string_length + 1):
            for start in range(ord('a'), ord('z') + 1):
                if rank[start] < length:
                    continue
                left = edges[start]
                right = [i for i in reverse_edges[i + length] if parent[i] != -1]
                if not right:
                    continue
                right_rep = right[0]
                for next_right in right[1:]:
                    unify(parent, rank, left[-1], next_right)
                unify(parent, rank, start, right_rep)
        root = []
        for i in range(ord('a'), ord('z') + 1):
            if parent[i] != -1:
                root.append(i)
        if len(root) == 1:
            print("YES")
        else:
            print("NO")

def unify(parent, rank, x, y):
    x_root = find(parent, x)
    y_root = find(parent, y)
    if x_root == y_root:
        return False
    if rank[x_root] < rank[y_root]:
        parent[x_root] = y_root
        rank[y_root] += rank[x_root]
    else:
        parent[y_root] = x_root
        rank[x_root] += rank[y_root]
    return True

def find(parent, x):
    if parent[x] == -1:
        return x
    parent[x] = find(parent, parent[x])
    return parent[x]
