from itertools import product, count

def palindrome(s):
    return s == s[::-1]

def split_palindromes(l):
    length = len(l) // 2
    if length * 2 != len(l):
        raise ValueError("Input is not long enough to be the double of a palindrome")

    palindromes = []
    i = 0
    while i < length:
        k, v = sorted(enumerate(l[i:length]), key=lambda x: (x[1], -x[0]))
