from collections import deque

def solve():
    sqrt_power = [pow(2, i) for i in range(32)]  # precompute square roots up to 16384
    blocks = []  # list to store the number of block lengths that can be created

    def dfs(node, power):
        if node < 0:
            return
        if len(blocks) <= power or blocks[-power - 1] < node:
            blocks.append(node)
        for i in range(2, node + 1):
            dfs(node - i, power + 1)

    for n in range(1, int(1e10)):
        dfs(n, 0)

    max_square = 0
    max_height = len(blocks)
    queue = deque([(0, max_height)])

    while len(queue) > 0:
        height, width = queue.popleft()
        if height == width and height > max_square:
            max_square = height
        for h in range(1, min(height + 1, max_height)):
            w = (width * height - pow(h, 2)) // (2 * (height - h))
            if w in sqrt_power and w <= max_height:
                queue.append((h, w))

