import itertools

def knight_moves(board, x, y):
    moves = {(x + dx * 2, y + dy) for dx, dy in itertools.product([1, -1], repeat=2)}
    board_indexes = set()

    def check_move(dx, dy):
        if x + dx <= 0 or x + dx > len(board) or y + dy <= 0 or y + dy > len(board[0]):
            return False
        return not board[x + dx][y + dy]

    for move in moves:
        if check_move(*move):
            moves.discard(move)

    filtered_moves = {move for move in moves if not board_indexes.add(move)}
    return list(filtered_moves)

def dfs(board, visited, row, col, moves):
    visited.add((row, col))

    if len(moves) == 1:
        return moves[0]

    for dr, dc in moves:
        if not visited.get((dr, dc)):
            result = dfs(board, visited, dr, dc, moves[1:])
            if result:
                return result

